    struct Entry ages[] = {{"Ada", 36}, {"Linus", 28}, {"Grace", 45}};
    size_t count = sizeof ages / sizeof ages[0];

    qsort(ages, count, sizeof ages[0], by_name);
    for (size_t i = 0; i < count; i++) {
